+     * Removes script elements, event handlers, and javascript: URLs.
+     * @param {Document} svgDoc The SVG DOM document to sanitize
+     */
+    _sanitizeSvgDom (svgDoc) {
+        // Remove script elements
+        const scripts = svgDoc.querySelectorAll('script');
+        scripts.forEach(script => script.remove());
+
+        // Remove foreignObject elements which can contain arbitrary HTML
+        const foreignObjects = svgDoc.querySelectorAll('foreignObject');
+        foreignObjects.forEach(fo => fo.remove());
+
+        // Remove event handler attributes and javascript: URLs from all elements
+        const allElements = svgDoc.querySelectorAll('*');
+        allElements.forEach(el => {
+            const attributes = Array.from(el.attributes);
+            attributes.forEach(attr => {
+                // Remove event handler attributes (onclick, onload, onerror, etc.)
+                if (attr.name.toLowerCase().startsWith('on')) {
+                    el.removeAttribute(attr.name);
+                }
+                // Remove javascript: URLs in href and xlink:href
+                if ((attr.name === 'href' || attr.name === 'xlink:href') &&
+                    attr.value.trim().toLowerCase().startsWith('javascript:')) {
+                    el.removeAttribute(attr.name);
+                }
+            });
+        });
+    }
